schema_ddl:
CREATE TYPE area_clinica AS ENUM ('cardiologia', 'ortopedia', 'neurologia', 'pronto_soccorso', 'pediatria');

CREATE TABLE pazienti_reparti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_fiscale TEXT NOT NULL UNIQUE,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    reparto area_clinica NOT NULL,
    data_ricovero DATE NOT NULL,
    priorita INT CHECK (priorita BETWEEN 1 AND 5)
);
